import assert from 'node:assert/strict';
import { INCLUDED,EXCLUDED,ALL,ID,SLOT,exactSet,appendOnly,validateOwnerSource } from './lib/owner-one-time-catchup.mjs';
const sample = ALL.map((doi,i)=>({doi,journal:i===0?'Nature Synthesis':'Organic Letters',title:'verified paper '+i,date:'2026-10-12',onlineDate:'2026-10-12',dateUnverified:false,authors:['Author '+i]}));
const compact={generatedAt:'2026-10-13T03:16:50.801Z',summary:{galleryDois:979,unresolved:7,criticalSourceFailures:0,sourceFamilyGaps:0,historicalCoverageLosses:0},unresolved:sample};
const audit={generatedAt:compact.generatedAt,summary:{...compact.summary}};
const yes=INCLUDED.map(doi=>{const row=sample.find(x=>x.doi===doi);return {...row,decision:'include',ownerDecision:'include',challengeDecision:'include',titleZh:'核对过的中文标题',reason:'经用户明确审核后确认予以收录',evidenceBasis:'Exact DOI identity and source provenance checked; owner title-based inclusion explicitly recorded.',challengeReason:'Owner manual decision applies to this DOI despite original evidence-pending status; no numerical experiment data is invented.',scopeAssessment:{primaryContribution:'取得具体研究新结果',preparativeTransformation:'以文献题名所述转化为对象',generalityEvidence:'完整制备范围尚未逐项核实',sourceEvidence:'基于 DOI 核对的题名和用户最终审核',boundaryChallenge:'缺少完整的实验范围证据，已如实披露'},...(['10.31635/ccschem.026.202608252','10.1021/acs.orglett.6c03893'].includes(doi)?{evidenceStatus:'owner_title_only_not_full_preparative_evidence'}:{})}});
const no=EXCLUDED.map(doi=>({...sample.find(x=>x.doi===doi),decision:'exclude',ownerDecision:'exclude',challengeDecision:'exclude',reason:'用户明确人工判断排除该 DOI',evidenceBasis:'Explicit owner title-based exclusion attached to exact DOI; pending historic review remains auditable.',challengeReason:'Publisher full text incomplete, so exclude is attributed to owner final decision, not to invented absent substrate evidence.'}));
const review={publicationSlot:SLOT,reviewType:'one_time_owner_title_override',ownerAuthorizationId:ID,accepted:yes,rejected:no,pending:[],summary:{reviewed:7,accepted:5,rejected:2,pending:0},qualityControl:{secondPassCompleted:true,unresolvedDisagreements:0}};
const staging={publicationSlot:SLOT,handoffGeneratedAt:compact.generatedAt,ownerAuthorizationId:ID,decisions:[...yes,...no]};
const authority={ownerApprovalId:ID,oneTimeOnly:true,noNewPublicationSchedule:true,originalSlot:SLOT,approved:INCLUDED.map(doi=>({doi})),excluded:EXCLUDED.map(doi=>({doi})),userInstruction:'1. 氧杂环丁烷→硫杂环丁烷：纳入；7. 卤键活化催化策略：纳入'};
assert.deepEqual(validateOwnerSource(authority,compact,audit,review,staging),[]);
assert.equal(exactSet(INCLUDED,INCLUDED),true);
assert.equal(exactSet([...INCLUDED,INCLUDED[0]],INCLUDED),false);
assert.equal(appendOnly({generatedAt:'old',papers:[{doi:'10.55/old'}]},{generatedAt:'old',papers:[{doi:'10.55/old'},...INCLUDED.map(doi=>({doi}))]},INCLUDED),true);
assert.equal(appendOnly({generatedAt:'old',papers:[{doi:'10.55/old'}]},{generatedAt:'tampered',papers:[{doi:'10.55/old'},...INCLUDED.map(doi=>({doi}))]},INCLUDED),false);
const altered=structuredClone(authority);altered.excluded=[{doi:'10.9999/other'},{doi:EXCLUDED[1]}];
assert.ok(validateOwnerSource(altered,compact,audit,review,staging).includes('owner_exclude_mismatch'));
const unknown=structuredClone(compact);unknown.unresolved[0].doi='10.5555/missing';
assert.ok(validateOwnerSource(authority,unknown,audit,review,staging).includes('unreviewed_or_unknown_doi'));
const bad=structuredClone(review);bad.accepted[0].ownerDecision='pending';
assert.ok(validateOwnerSource(authority,compact,audit,bad,staging).some(x=>x.startsWith('owner_decision_not_applied')));
const unsupported=structuredClone(review);unsupported.accepted.find(x=>x.doi==='10.1021/acs.orglett.6c03893').evidenceStatus='complete';
assert.ok(validateOwnerSource(authority,compact,audit,unsupported,staging).some(x=>x.startsWith('unverified_scope_not_disclosed')));
console.log(JSON.stringify({ok:true,testCases:9,policy:'exact one-time owner admission; five include and two exclude only; no off-slot schedule change'}));
